entries[73621] = { ["name"] = "Der Perforator", ["text"] = "Wirken in 3 sek.\nTools: Juweliersset\nReagenzien:\nHeliodor , Dämonenauge , Traumsmaragd , Gluttopas , Ozeansaphir , Infernorubin\nDer Perforator\n(0)\nWird beim Anlegen gebunden\nEinhändig Faustwaffe\n660 - 1,226 Schaden Tempo 2.60\n(362.69 Schaden pro Sekunde)\n+95 Beweglichkeit\n+172 Ausdauer\nErhöht Eure Meisterschaftswertung um + 38.\n\nRoter Sockel\nSockelbonus: +10 Meisterschaftswertung\n\nHaltbarkeit 65 / 65\n83\nAnlegen: Erhöht die kritische Trefferwertung um 87." }
