entries[73651] = { ["name"] = "Gesundung", ["text"] = "30 Energie 100 Meter Reichweite\nSofort\nFinishing-Move, der alle Combopunkte auf einem nahen Ziel verbraucht, um alle 3 Sek. [ Verbesserte Gesundung : 4 ] [Quellwert]% Eurer maximalen Gesundheit wiederherzustellen. Hält pro Combopunkt länger an:\n1 Punkt: 6 Sek.\n2 Punkte: 12 Sek.\n3 Punkte: 18 Sek.\n4 Punkte: 24 Sek.\n5 Punkte: 30 Sek.", ["unresolvedValues"] = true }
