entries[73680] = { ["name"] = "Elemente entfesseln", ["text"] = "7% von Grundmana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nFokussiert die Elementarkraft, die in der Bewaffnung des Schamanen gebündelt ist und setzt sie frei. Der konzentrierte Effekt entspricht der entfesselten Verzauberung. [ Beidhändigkeit : Wenn beide Waffen mit der gleichen Verzauberung versehen sind, wird nur eine entfesselt werden ]\nDie Einzelheiten der Entfesslungseffekte sind in den Tooltips der jeweiligen Waffenverzauberungen erfasst." }
entries[73681] = { ["name"] = "Wind entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nEntfesselt die auf der Waffe des Schamanen liegende Windzornverzauberung, wodurch einem feindlichen Ziel 175% Waffenschaden zugefügt werden. Zudem wird das Nahkampfangriffstempo des Schamanen um 40% erhöht. Hält 6 Waffenschwünge oder 12 Sek. lang an." }
entries[73682] = { ["name"] = "Frost entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt die auf der Waffe des Schamanen liegende Frostbrandverzauberung, wodurch einem feindlichen Ziel 873 Frostschaden zugefügt werden und sein Bewegungstempo 5 Sek. lang um 50 % verringert wird. Der Effekt wird verstärkt, wenn das Ziel bereits von einem bewegungsverringernden Frosteffekt betroffen ist." }
entries[73683] = { ["name"] = "Flammen entfesseln", ["text"] = "100 Meter Reichweite\nSofort\nEntfesselt die auf der Waffe des Schamanen liegende Flammenzungenverzauberung, wodurch einem feindlichen Ziel 1118 Feuerschaden zugefügt werden und der verursachte Schaden des nächsten Feuerzaubers des Schamanen um 20 % erhöht wird." }
entries[73684] = { ["name"] = "Erde entfesseln", ["text"] = "100 Meter Reichweite\nSofort 15 sek. Abklingzeit\nEntfesselt die auf der Waffe des Schamanen liegende Felsbeißerverzauberung, wodurch ein feindliches Ziel gezwungen wird, den Schamanen 5 Sek. lang anzugreifen." }
entries[73685] = { ["name"] = "Leben entfesseln", ["text"] = "100 Meter Reichweite\nSofort 15 sek. Abklingzeit\nEntfesselt die auf der Waffe des Schamanen liegende Lebensgeisterverzauberung, wodurch ein befreundetes Ziel um 1996 geheilt und der Effekt der nächsten direkten Heilung des Schamanen um 20 % erhöht wird." }
